<template><q-page class="q-pa-lg"><div class="text-overline text-primary">ORGANIZATION OVERVIEW</div><div class="page-title">Operational overview</div><p class="muted">Monitor employees, departments, and current organizational activity.</p><div class="text-caption muted">{{ today }}</div><DashboardCards :cards="cards"/></q-page></template>
<script setup>import {ref,onMounted} from 'vue';import {authStore} from '../stores/authStore';import api from '../services/api';import DashboardCards from '../components/DashboardCards.vue';const today=new Intl.DateTimeFormat('en',{dateStyle:'full'}).format(new Date());const cards=ref([{label:'Total Employees',icon:'groups',color:'indigo',key:'totalEmployees'},{label:'Active Employees',icon:'verified_user',color:'positive',key:'activeEmployees'},{label:'Inactive Employees',icon:'person_off',color:'orange',key:'inactiveEmployees'},{label:'Total Departments',icon:'business',color:'indigo',key:'totalDepartments'}]);onMounted(async()=>{try{const stats=(await api.get('/dashboard/admin')).data.data;cards.value=cards.value.map(c=>({...c,value:stats[c.key],preview:false}))}catch{}})</script>
